# Build output grid - start with background of 5s
test_output = [[5]*29 for _ in range(14)]

# Place all 8s (they stay where they are)
for r in range(14):
    for c in range(29):
        if test_input[r][c] == 8:
            test_output[r][c] = 8

# Place all 2s (they stay where they are)
for r in range(14):
    for c in range(29):
        if test_input[r][c] == 2:
            test_output[r][c] = 2

# Identify all 1s and 6s
ones = [(r, c) for r in range(14) for c in range(29) if test_input[r][c] == 1]
sixes = [(r, c) for r in range(14) for c in range(29) if test_input[r][c] == 6]

print(f"Original 1s: {ones}")
print(f"Original 6s: {sixes}")

# Move 1s up by 1 and place them
for r, c in ones:
    if r > 0:
        test_output[r-1][c] = 1

# Place 6s where they stay
for r, c in sixes:
    test_output[r][c] = 6

# Place 4s: from each 2 at (r,c), place 4s at (r-2, c-1), (r-2, c+1), (r-1, c-1), (r-1, c+1)
twos = [(r, c) for r in range(14) for c in range(29) if test_input[r][c] == 2]
print(f"Twos: {twos}")

for r, c in twos:
    for dr, dc in [(-2, -1), (-2, 1), (-1, -1), (-1, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 14 and 0 <= nc < 29:
            test_output[nr][nc] = 4

# Place 8s from each ORIGINAL 1 (X pattern at diagonals)
original_ones = ones
print(f"Placing 8s around original 1s at: {original_ones}")

for r, c in original_ones:
    for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 14 and 0 <= nc < 29:
            if test_output[nr][nc] != 8 and test_output[nr][nc] != 1:
                test_output[nr][nc] = 8

# Place 7s: from each NEW 1 (up 1), place 7s at (+) pattern
new_ones = [(r-1, c) for r, c in ones if r > 0]
print(f"Placing 7s around new 1s at: {new_ones}")

for r, c in new_ones:
    for dr, dc in [(-1, 0), (0, -1), (0, 1), (1, 0)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 14 and 0 <= nc < 29:
            if test_output[nr][nc] not in [8, 1, 2]:
                test_output[nr][nc] = 7

# Print the result grid
print("\n== OUTPUT GRID ==")
for r in range(14):
    row = test_output[r]
    print(" ".join(f"{v:2}" for v in row))
